require_once __DIR__.'/config/config.php';require_login();$uid=(int)$_SESSION['user_id'];$errors=[];$stmt=$conn->prepare('SELECT id,animal_code,name FROM animals WHERE owner_id=? AND status="Active" ORDER BY animal_code');$stmt->bind_param('i',$uid);$stmt->execute();$animals=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$animal_id=(int)($_POST['animal_id']??0);$date=$_POST['movement_date']??'';$origin=trim($_POST['origin_location']??'');$dest=trim($_POST['destination_location']??'');$reason=trim($_POST['movement_reason']??'');$doc=trim($_POST['document_reference']??'');$notes=trim($_POST['notes']??'');if(!$animal_id||!$date||!$origin||!$dest)$errors[]='Animal, date, origin and destination are required.';$check=$conn->prepare('SELECT id FROM animals WHERE id=? AND owner_id=?');$check->bind_param('ii',$animal_id,$uid);$check->execute();if(!$check->get_result()->num_rows)$errors[]='Choose an animal from your own records.';if(!$errors){$stmt=$conn->prepare('INSERT INTO movement_records(animal_id,movement_date,origin_location,destination_location,movement_reason,document_reference,notes,entered_by) VALUES(?,?,?,?,?,?,?,?)');$stmt->bind_param('issssssi',$animal_id,$date,$origin,$dest,$reason,$doc,$notes,$uid);$stmt->execute();flash('Movement record saved.');header('Location: movements.php');exit;}}
$page_title='Record movement';require __DIR__.'/includes/header.php';?>
<?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><?php if(!$animals):?><div class="alert info">Register an active animal before recording a movement. <a class="link" href="animal_add.php">Register livestock →</a></div><?php else:?><div class="form-card"><div class="panel-heading"><div><h3>Movement details</h3><p>Enter the movement details from your records and retain any official documents separately.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field full"><label>Livestock *</label><select name="animal_id" required><option value="">Choose livestock</option><?php foreach($animals as $a):?><option value="<?=$a['id']?>"><?=e($a['animal_code'].' '.($a['name']?:''))?></option><?php endforeach;?></select></div><div class="field"><label>Movement date *</label><input type="date" name="movement_date" required value="<?=date('Y-m-d')?>"></div><div class="field"><label>Reason</label><select name="movement_reason"><option value="">Choose if applicable</option><option>Grazing</option><option>Veterinary service</option><option>Market</option><option>Sale / transfer</option><option>Other</option></select></div><div class="field"><label>Origin *</label><input name="origin_location" required maxlength="140" placeholder="Village / dip tank / farm"></div><div class="field"><label>Destination *</label><input name="destination_location" required maxlength="140" placeholder="Village / dip tank / farm"></div><div class="field full"><label>Official document reference (optional)</label><input name="document_reference" maxlength="120" placeholder="Reference only; this system does not issue permits"></div><div class="field full"><label>Notes</label><textarea name="notes"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Save movement</button><a class="btn btn-light" href="movements.php">Cancel</a></div></form></div><?php endif;?><?php require __DIR__.'/includes/footer.php';?>
